head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// 호출메뉴ID를 식별하기 위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common_digital.js");
// 상장관련공통함수
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
scwin.vScrenID = "ULDSTF70034.xml";
scwin.fr_MktId = $c.lcd.fn_getMktId(); // 시장구분코드(유가, 코스닥) 전체), 기준은 로그인 사용자의 부서 소속을 기준으로 한다.

scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vIsurCd = "";
scwin.vSecuGrpId = "";
scwin.vLIST_STAT_CD = "Y";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

// 상장폐지 조회(Tab 1)
scwin.fn_search = function() {
    var url = "/digital/DigitalListinvstg.do?method=selectDigitalDelist";
    if (rdo_1_1.getValue() == "1") {
        //종목조회
        url += "&DIV_IDX=" + DIV_IDX_DIGITAL_DELLIST_LIST_ISU + "&TRS_IDX=" + TRS_IDX_SELECT + "&ISU_CD=" + txb_ISU_CD.getValue();
    } else if (rdo_1_2.getValue() == "1") {
        // 상장신청인 조회		
        if ($c.stf.getObjectValue(txb_ISUR_CD1) == "") {
            url += "&DIV_IDX=" + DIV_IDX_DIGITAL_DELLIST_LIST_ALL + "&TRS_IDX=" + TRS_IDX_SELECT;
        } else {
            url += "&DIV_IDX=" + DIV_IDX_DIGITAL_DELLIST_LIST_CORP + "&TRS_IDX=" + TRS_IDX_SELECT + "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD1);
        }
    }
    url += "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts.DataID = encodeURI(url);
    dts.reset();
    $c.cm.ShowWin(grd);
};

// 만기에 의한 상장폐지(Tab2)
scwin.fn_search2 = function() {
    var url = "/digital/DigitalListinvstg.do?method=selectDigitalDelist";
    url += "&DIV_IDX=" + DIV_IDX_DIGITAL_DELLIST_LIST_CORP + "&TRS_IDX=" + TRS_IDX_SELECT + "&ISUR_CD=99999";
    url += "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts2.DataID = encodeURI(url);
    dts2.reset();
    $c.cm.ShowWin(grd2);
};



// dialog 호출용 함수
// 상장신청인 호출관련
scwin.fn_GetParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션

    arrPar[0] = $c.stf.getObjectValue(txb_ISUR_CD1); // 코드값을 포함할 컨트롤
    arrPar[1] = $c.stf.getObjectValue(txb_COM_NM1); // 명칭값을 포함할 컨트롤

    return arrPar.length;
};
scwin.fn_SetParIsur = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        scwin.fn_changeRadioBtn(2);
        if (tabList.getSelectedTabIndex() == "1") {
            txb_ISUR_CD1.setValue(arrPar[0].ISUR_CD);
            txb_COM_NM1.setValue(arrPar[0].ISUR_NM);
            scwin.fn_search();
        }
        scwin.vIsurCd = arrPar[0].ISUR_CD;
    }
    scwin.vLIST_STAT_CD = arrPar[0].LIST_STAT_CD;
    if (scwin.vLIST_STAT_CD == "D") {
        if (tabList.getSelectedTabIndex() == "1") {
            img_Regist.setDisabled(true);
            img_Regist.src = "../img/btn_new_d.gif";
        } else {
            img_Regist2.setDisabled(true);
            img_Regist2.src = "../img/btn_new_d.gif";
        }
    } else {
        if (tabList.getSelectedTabIndex() == "1") {
            img_Regist.setDisabled(false);
            img_Regist.src = "../img/btn_new.gif";
        } else {
            img_Regist2.setDisabled(false);
            img_Regist2.src = "../img/btn_new.gif";
        }
    }
};



// dialog 호출용 함수
// 종목명 호출관련
scwin.fn_GetParIsu = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = ""; // 코드값을 포함할 컨트롤
    if (tabList.getSelectedTabIndex() == "1") {
        arrPar[1] = $c.stf.getObjectValue(txb_ISU_NM); // 명칭값을 포함할 컨트롤

    }
    arrPar[2] = "";
    return arrPar.length;
};
scwin.fn_SetParIsu = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        scwin.fn_changeRadioBtn(1);
        if (tabList.getSelectedTabIndex() == "1") {
            txb_ISU_CD.setValue(arrPar[0].ISU_CD);
            txb_ISU_NM.setValue(arrPar[0].ISU_KOR_ABBRV);
            scwin.fn_search();
        }
        scwin.vIsurCd = arrPar[0].ISUR_CD;
        scwin.vSecuGrpId = arrPar[0].SECUGRP_ID;
    }
    scwin.vLIST_STAT_CD = arrPar[0].LIST_STAT_CD;
    if (scwin.vLIST_STAT_CD == "D") {
        if (tabList.getSelectedTabIndex() == "1") {
            img_Regist.setDisabled(true);
            img_Regist.src = "../img/btn_new_d.gif";
        } else {
            img_Regist2.setDisabled(true);
            img_Regist2.src = "../img/btn_new_d.gif";
        }
    } else {
        if (tabList.getSelectedTabIndex() == "1") {
            img_Regist.setDisabled(false);
            img_Regist.src = "../img/btn_new.gif";
        } else {
            img_Regist2.setDisabled(false);
            img_Regist2.src = "../img/btn_new.gif";
        }
    }
};
scwin.fn_GetParUpdate = function(arrPar) {
    // 넘길 인수를 지정하는 펑션

    if (rdo_1_1.getValue() == "1") {
        arrPar[0] = scwin.vIsurCd; // 발행기관코드값
        arrPar[1] = txb_ISU_NM.getValue(); // 종목명
        arrPar[5] = txb_ISU_CD.getValue(); // 종목코드값
        arrPar[6] = "1"; // 선택 구분(1:종목, 2:발행회사, 3:전체)

    } else if (rdo_1_2.getValue() == "1") {
        if ($c.stf.getObjectValue(txb_ISUR_CD1) == "") {
            arrPar[0] = scwin.vIsurCd; // 발행기관코드값
            arrPar[1] = dts.getCellData(dts.getRowPosition(), "COM_NM"); // 발행기관명
            arrPar[5] = ""; // 종목코드값
            arrPar[6] = "3"; // 선택 구분(1:종목, 2:발행회사, 3:전체)

        } else {
            arrPar[0] = scwin.vIsurCd; // 발행기관코드값
            arrPar[1] = dts.getCellData(dts.getRowPosition(), "COM_NM"); // 발행기관명
            arrPar[5] = ""; // 종목코드값
            arrPar[6] = "2"; // 선택 구분(1:종목, 2:발행회사, 3:전체)

        }
    }
    arrPar[2] = scwin.vSecuGrpId;
    arrPar[3] = scwin.fr_MktId; // 시장구분
    arrPar[4] = dts.getCellData(dts.getRowPosition(), "bz_procs_no"); // 업무처리번호		
    arrPar[7] = dts.getCellData(dts.getRowPosition(), "DSC_YN"); // 공시여부 


    return arrPar.length;
};
scwin.fn_GetParNew = function(arrPar) {
    // 신규생성시 지정하는 평션
    if (rdo_1_1.getValue() == "1") {
        arrPar[0] = scwin.vIsurCd; // 발행기관코드값
        arrPar[1] = txb_ISU_NM.getValue(); // 종목명

        arrPar[5] = txb_ISU_CD.getValue(); // 종목코드값
        arrPar[6] = "1"; // 선택 구분(1:종목, 2:발행회사, 3:전체)

    } else if (rdo_1_2.getValue() == "1") {
        if ($c.stf.getObjectValue(txb_ISUR_CD1) == "") {
            arrPar[0] = ""; // 발행기관코드값
            arrPar[1] = ""; // 발행기관명
            arrPar[5] = ""; // 종목코드값
            arrPar[6] = "3"; // 선택 구분(1:종목, 2:발행회사, 3:전체)

        } else {
            arrPar[0] = $c.stf.getObjectValue(txb_ISUR_CD1); // 발행기관코드값
            arrPar[1] = $c.stf.getObjectValue(txb_COM_NM1); // 발행기관명
            arrPar[5] = ""; // 종목코드값
            arrPar[6] = "2"; // 선택 구분(1:종목, 2:발행회사, 3:전체)

        }
    }
    arrPar[2] = scwin.vSecuGrpId; // 증권그룹구분
    arrPar[3] = scwin.fr_MktId; // 시장구분
    arrPar[4] = ""; // 신규작성시 업무처리번호는 없다.
    arrPar[7] = ""; // 공시여부

};
scwin.fn_GetParUpdate2 = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = scwin.vIsurCd; // 발행기관코드값
    arrPar[1] = ""; // 발행기관명
    arrPar[2] = scwin.vSecuGrpId;
    arrPar[3] = scwin.fr_MktId; // 시장구분
    arrPar[4] = dts2.getCellData(dts2.getRowPosition(), "bz_procs_no"); // 업무처리번호
    arrPar[5] = ""; // 종목코드값
    arrPar[6] = "3"; // 선택 구분(1:종목, 2:발행회사, 3:전체)		
    arrPar[7] = dts2.getCellData(dts2.getRowPosition(), "DSC_YN"); // 공시여부 

    return arrPar.length;
};
scwin.fn_GetParNew2 = function(arrPar) {
    // 신규생성시 지정하는 평션
    arrPar[0] = ""; // 발행기관코드값
    arrPar[1] = ""; // 발행기관명		
    arrPar[2] = scwin.vSecuGrpId; // 증권그룹구분	
    arrPar[3] = scwin.fr_MktId; // 시장구분
    arrPar[4] = ""; // 신규작성시 업무처리번호는 없다.
    arrPar[5] = ""; // 종목코드값
    arrPar[6] = "3"; // 선택 구분(1:종목, 2:발행회사, 3:전체)

};
scwin.fn_new_create_frame = async function() {
    await $c.frame.CreateDialogFrame("ULDSTF70034_n1", "../digital/ULDSTF70034_N1.gfm", " 상장폐지", 200, 100, 740, 450, "window");
    scwin.fn_search(); // 다이얼로그 창이 닫히면 조회를 보낸다.

};
scwin.fn_new_create_frame2 = async function() {
    await $c.frame.CreateDialogFrame("ULDSTF70034_n2", "../digital/ULDSTF70034_n2.gfm", " 만기에 의한 상장폐지", 200, 100, 770, 470, "window");
    scwin.fn_search2(); // 다이얼로그 창이 닫히면 조회를 보낸다.

};
scwin.fn_newpre_create_frame = async function() {
    await $c.frame.CreateDialogFrame("ULDSTF70034_p1", "../digital/ULDSTF70034_p1.gfm", " 상장폐지", 200, 100, 720, 450, "window");
    scwin.fn_search(); // 다이얼로그 창이 닫히면 조회를 보낸다.

};
scwin.fn_newpre_create_frame2 = async function() {
    await $c.frame.CreateDialogFrame("ULDSTF70034_p2", "../digital/ULDSTF70034_p2.gfm", " 만기에 의한 상장폐지", 200, 100, 770, 470, "window");
    scwin.fn_search2(); // 다이얼로그 창이 닫히면 조회를 보낸다.

};
scwin.fn_changeRadioBtn = function(idx) {
    if (idx == "1") {
        txb_ISUR_CD1.setValue("");
        txb_COM_NM1.setValue("");
        rdo_1_1.setValue("1");
        rdo_1_2.setValue("2");
    } else if (idx == "2") {
        txb_ISU_CD.setValue("");
        txb_ISU_NM.setValue("");
        rdo_1_1.setValue("2");
        rdo_1_2.setValue("1");
    }
};
scwin.tabList_OnSelChanged = function(nIndex) {
    if (nIndex == 1) {
        rdo_1_1.setValue("1");
        rdo_1_2.setValue("2");
        txb_ISU_CD.setValue("");
        txb_ISU_NM.setValue("");
        txb_ISUR_CD1.setValue("");
        txb_COM_NM1.setValue("");
        scwin.fn_search();
    } else if (nIndex == 2) {
        scwin.fn_search2();
    }
};
scwin.dts_OnLoadError = function() {
    $c.stf.alert_error(dts);
};
scwin.dts_OnLoadCompleted = function(rowcount) {
    txb_TotCnt.setValue("총 건수 : " + rowcount);
    //dts.RowPosition = rowcount;
    $c.cm.CloseWin(rowcount, grd);
};
scwin.dts2_OnLoadError = function() {
    $c.stf.alert_error(dts2);
};
scwin.dts2_OnLoadCompleted = function(rowcount) {
    txb_TotCnt2.setValue("총 건수 : " + rowcount);
    //dts2.RowPosition = rowcount;
    $c.cm.CloseWin(rowcount, grd2);
};
scwin.img_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.img_Regist_onclick = function() {
    if (tabList.getSelectedTabIndex() == 1) {
        // 종목 선택
        if (rdo_1_1.getValue() == "1") {
            if (txb_ISU_CD.getValue() == "") {
                $c.win.alert($c.stf.getMessageParam("MSG-0015", ""));
                return true;
            }
        }
        scwin.fn_GetPar = fn_GetParNew;
        scwin.fn_SetPar = undefined;
        if (rdo_1_2.getValue() == "1") {
            scwin.fn_new_create_frame();
        } else {
            scwin.fn_newpre_create_frame();
        }
    } else {
        scwin.fn_GetPar = fn_GetParNew2;
        scwin.fn_SetPar = undefined;
        scwin.fn_new_create_frame2();
    }
};
scwin.img_Excel_onclick = function() {
    //엑셀저장
    if (tabList.getSelectedTabIndex() == 1) {
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
        if (dts.getTotalRow() > 0) {
            $c.data.downloadGridViewExcel(grd, "상장폐지내역", "", "8");
        } else {
            $c.win.alert(NO_EXCEL_DATA);
        }
    } else {
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
        if (dts2.getTotalRow() > 0) {
            $c.data.downloadGridViewExcel(grd2, "만기에 의한 상장폐지내역", "", "8");
        } else {
            $c.win.alert(NO_EXCEL_DATA);
        }
    }
};
scwin.grd_OnDblClick = function(row, colid) {
    scwin.vIsurCd = dts.getCellData(dts.getRowPosition(), "ISUR_CD");
    scwin.fn_GetPar = fn_GetParUpdate; // 수정시 인수를 넘기는 function을 fn_GetPar란 변수에 할당, (팝업화면에서 참조하는 변수명이 fn_GetPar임)
    scwin.fn_SetPar = undefined;
    scwin.fn_newpre_create_frame();
};
scwin.grd2_OnDblClick = function(row, colid) {
    scwin.vIsurCd = dts2.getCellData(dts2.getRowPosition(), "ISUR_CD");
    scwin.fn_GetPar = fn_GetParUpdate2; // 수정시 인수를 넘기는 function을 fn_GetPar란 변수에 할당, (팝업화면에서 참조하는 변수명이 fn_GetPar임)
    scwin.fn_SetPar = undefined;
    scwin.fn_newpre_create_frame2();
};
scwin.img_Search_onclick = function() {
    if (rdo_1_1.getValue() == "1") {
        if (txb_ISU_CD.getValue() == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-0015", ""));
            return true;
        }
    }
    scwin.fn_search();
};
scwin.img_Search2_onclick = function() {
    scwin.fn_search2();
};
scwin.btn_iSU_CD_onclick = function() {
    scwin.fn_GetPar = fn_GetParIsu;
    scwin.fn_SetPar = fn_SetParIsu;
    $c.lcd.fn_PopFindDigitalIsuAll();
};
scwin.rdo_1_1_OnClick = function() {
    //rdo_1_2.CodeValue ="2";
    scwin.fn_changeRadioBtn(1);
};
scwin.rdo_1_2_OnClick = function() {
    //rdo_1_1.CodeValue ="2";
    scwin.fn_changeRadioBtn(2);
    scwin.fn_search();
};
scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox(pan_Cnd);
    $c.libRoundPanel.PanelToGroupBox(pan_Cnd2);
    rdo_1_1.setValue("1");
};
scwin.img_COM_NM1_onclick = function() {
    scwin.fn_GetPar = fn_GetParIsur;
    scwin.fn_SetPar = fn_SetParIsur;
    $c.lcd.fn_PopFindDigitalIsurAll();
};
scwin.txb_ISU_CD_onchange = function() {
    $c.stf.setObjectValue(txb_ISU_NM, "");
};
scwin.txb_ISUR_CD1_onchange = function() {
    $c.stf.setObjectValue(txb_COM_NM1, "");
};
